import csv
import io


def parse_csv(raw_csv: str):
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"')
    parsed = list(reader)

    header_index = None
    for index, row in enumerate(parsed):
        if len(row) >= 2 and sum(bool(cell.strip()) for cell in row) >= 2:
            header_index = index
            break

    if header_index is None:
        header_index = next((i for i, row in enumerate(parsed) if row), None)

    if header_index is None:
        return {"columns": [], "rows": []}

    header = parsed[header_index]
    data_rows = parsed[header_index + 1:]
    width = max([11, len(header)] + [len(row) for row in data_rows])

    columns = header + [""] * (width - len(header))
    rows = [row + [""] * (width - len(row)) for row in data_rows]

    return {"columns": columns, "rows": rows}
